K.pill(2, '20', 'ms', '');
K.nodes(['app', 'entra'], ['entra']);
K.wires({ a1: ['flow', 'hot'] });
K.lit(1);

MSD.after(400,  function(){ MSD.punch('#lj-n-entra', 2); MSD.sfx.whoosh(); });
