K.wires({ a1: ['flow', 'ok'], a2: ['flow', 'hot'], mfa: ['flow', 'ok'] });
K.J(K.VERIFY, { active: 2 });

MSD.after(400,  function(){ MSD.punch('#lj-n-api', 2); MSD.sfx.blip(2); });
MSD.after(1200, function(){ K.J(K.VERIFY, { active: 4 }); MSD.punch('#lj-ln-4', 4); MSD.sfx.lock(); });
MSD.after(2100, function(){ K.pill(2, '1460', 'ms', ''); MSD.punch('#lj-pill-1', 5); });

